.exam-grid > .exam-card:nth-child(1)  { --stagger-i: 0; }
.exam-grid > .exam-card:nth-child(2)  { --stagger-i: 1; }
.exam-grid > .exam-card:nth-child(3)  { --stagger-i: 2; }
.exam-grid > .exam-card:nth-child(4)  { --stagger-i: 3; }
.exam-grid > .exam-card:nth-child(5)  { --stagger-i: 4; }
.exam-grid > .exam-card:nth-child(6)  { --stagger-i: 5; }
.exam-grid > .exam-card:nth-child(7)  { --stagger-i: 6; }
.exam-grid > .exam-card:nth-child(8)  { --stagger-i: 7; }
.exam-grid > .exam-card:nth-child(9)  { --stagger-i: 8; }
.exam-grid > .exam-card:nth-child(10) { --stagger-i: 9; }
.exam-grid > .exam-card:nth-child(11) { --stagger-i: 10; }
.exam-grid > .exam-card:nth-child(12) { --stagger-i: 11; }

