/* === css/home_modals.css === */
/* ==========================================================================
   Share Achievement Postcard Modal (1:1 Match Mockup)
   ========================================================================== */
.share-card-modal-overlay {
    position: fixed;
    inset: 0;
    z-index: 9999;
    background: rgba(15, 23, 42, 0.72);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px 16px;
    box-sizing: border-box;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.28s cubic-bezier(0.16, 1, 0.3, 1);
}

.share-card-modal-overlay.is-active {
    opacity: 1;
    pointer-events: auto;
}

.share-card-modal-container {
    width: 100%;
    max-width: 336px;
    display: flex;
    flex-direction: column;
    align-items: center;
    transform: scale(0.92) translateY(12px);
    transition: transform 0.32s cubic-bezier(0.34, 1.45, 0.64, 1);
}

.share-card-modal-overlay.is-active .share-card-modal-container {
    transform: scale(1) translateY(0);
}

.share-achievement-card {
    width: 100%;
    background: #FFFFFF;
    border-radius: 28px;
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.35), 0 2px 10px rgba(0, 0, 0, 0.08);
    padding: 20px 18px 18px 18px;
    box-sizing: border-box;
    position: relative;
    user-select: none;
    -webkit-user-select: none;
}

/* Header */
.share-card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
}

.share-card-brand {
    font-size: 12.5px;
    font-weight: 850;
    color: #334155;
    letter-spacing: 0.02em;
}

.share-card-date {
    font-size: 12px;
    font-weight: 700;
    color: #64748B;
}

/* Hero Illustration Frame (4:3 黄金比例居中裁剪) */
.share-card-hero-frame {
    width: 100%;
    aspect-ratio: 4 / 3;
    border-radius: 20px;
    overflow: hidden;
    position: relative;
    margin: 12px 0 12px 0;
    box-shadow: 0 4px 18px rgba(0, 0, 0, 0.08);
    background: #E2E8F0;
}

.share-card-hero-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center center;
    display: block;
    transition: transform 0.4s ease;
}

/* Metrics Capsule */
.share-card-metrics-capsule {
    background: #F8FAFC;
    border: 1px solid rgba(226, 232, 240, 0.9);
    border-radius: 18px;
    padding: 12px 6px;
    display: grid;
    grid-template-columns: 1fr auto 1fr auto 1fr;
    align-items: center;
    margin-top: 0;
    box-sizing: border-box;
}

.share-metric-col {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 0 4px;
}

.share-metric-val {
    font-size: 15.5px;
    font-weight: 900;
    color: #0F172A;
    line-height: 1.15;
    letter-spacing: -0.02em;
    white-space: nowrap;
}

.share-metric-lbl {
    font-size: 10px;
    font-weight: 700;
    color: #64748B;
    margin-top: 3px;
    white-space: nowrap;
}

.share-metric-divider {
    width: 1px;
    height: 22px;
    background: rgba(226, 232, 240, 0.85);
}

/* Footer Profile & QR */
.share-card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 15px;
    padding-top: 12px;
    border-top: 1px solid rgba(241, 245, 249, 0.95);
}

.share-card-user-info {
    display: flex;
    align-items: center;
    gap: 10px;
}

.share-card-avatar-wrap {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    overflow: hidden;
    background: #E2E8F0;
    border: 1.5px solid #FFFFFF;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    flex-shrink: 0;
}

.share-card-avatar {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.share-card-user-texts {
    display: flex;
    flex-direction: column;
}

.share-card-username {
    font-size: 14.5px;
    font-weight: 850;
    color: #0F172A;
    letter-spacing: -0.01em;
    line-height: 1.25;
}

.share-card-qr-box {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex-shrink: 0;
}

.share-card-qr-img {
    width: 52px;
    height: 52px;
    border-radius: 8px;
    border: 1px solid rgba(0, 0, 0, 0.05);
    background: #FFFFFF;
    display: block;
}

.share-card-qr-tip {
    font-size: 9px;
    font-weight: 750;
    color: #94A3B8;
    margin-top: 3px;
    letter-spacing: -0.01em;
}

/* Action Buttons */
.share-modal-action-bar {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 16px;
    width: 100%;
    justify-content: center;
    box-sizing: border-box;
    padding: 0 4px;
}

.share-action-btn {
    border: none;
    border-radius: 999px;
    cursor: pointer;
    font-family: inherit;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    touch-action: manipulation;
    transition: transform 0.2s cubic-bezier(0.34, 1.45, 0.64, 1), box-shadow 0.2s ease;
    white-space: nowrap;
}

.share-action-btn:active {
    transform: scale(0.95);
}

.btn-share-back {
    background: rgba(255, 255, 255, 0.92);
    color: #475569;
    font-size: 13px;
    font-weight: 750;
    padding: 11px 22px;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12);
    flex-shrink: 0;
}

.btn-share-forward {
    flex: 1;
    min-width: 0;
    background: #0F172A;
    color: #FFFFFF;
    font-size: 13.5px;
    font-weight: 800;
    padding: 11px 20px;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.28);
}

/* ==========================================================================
   Leaderboard Bottom Sheet Drawer Modal (1:1 照搬 单词Toy RankModal 规范)
   严格限定在手机容器 (#app-layout) 内部呈现，绝不超出机身外侧
   ========================================================================== */
.rank-modal-overlay {
    position: fixed !important;
    inset: 0 !important;
    width: 100% !important;
    height: 100% !important;
    z-index: 10000 !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-end !important;
    align-items: stretch !important;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity 0.35s cubic-bezier(0.16, 1, 0.3, 1), visibility 0s linear 0.35s;
    user-select: none;
    -webkit-user-select: none;
    overflow: hidden !important;
    box-sizing: border-box !important;
}

.rank-modal-overlay.is-active {
    opacity: 1 !important;
    visibility: visible !important;
    pointer-events: auto !important;
    transition: opacity 0.35s cubic-bezier(0.16, 1, 0.3, 1), visibility 0s linear 0s;
}

body.rank-modal-open {
    overflow: hidden !important;
}

body.rank-modal-open #app-layout {
    overflow: hidden !important;
}

.rank-modal-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    cursor: pointer;
}

.rank-drawer-content {
    position: relative;
    z-index: 2;
    width: 100%;
    max-width: 100%;
    margin: 0;
    background: #FFFFFF !important;
    background-color: #FFFFFF !important;
    opacity: 1 !important;
    border-top-left-radius: 32px;
    border-top-right-radius: 32px;
    max-height: 85vh;
    height: 75vh;
    display: flex;
    flex-direction: column;
    box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.18);
    padding: 14px 18px calc(24px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px))) 18px;
    box-sizing: border-box;
    border-top: 1px solid rgba(0, 0, 0, 0.05);
    transform: translateY(100%);
    transition: transform 0.36s cubic-bezier(0.16, 1, 0.3, 1);
    will-change: transform;
}

.rank-modal-overlay.is-active .rank-drawer-content {
    transform: translateY(0) !important;
}

/* 抽屉顶部把手 */
.rank-drawer-handle-wrap {
