/* === css/home_tabbar.css === */
/* ==========================================================================
   Home Liquid-Glass Tab Bar + 统计 / 我的 Tab Pages
   (1:1 visual language ported from 单词Toy LiquidGlassTabBar / StudyStatsModal / SettingsModal)
   ========================================================================== */

/* -------------------------------------------------------------------------
   1. Floating Liquid-Glass Tab Bar
   ------------------------------------------------------------------------- */
.home-tabbar {
    --htb-ease: cubic-bezier(0.32, 0.72, 0, 1);
    --htb-spring: cubic-bezier(0.3, 1.25, 0.45, 1);
    --hx: 50%;
    --htb-veil: 0.34;
    --htb-sh: 0.28;
    position: fixed;
    z-index: 125;
    left: 50%;
    bottom: calc(14px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px)));
    transform: translateX(-50%);
    display: none;
    align-items: center;
    height: 48px;
    padding: 4px;
    border-radius: 999px;
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
    -webkit-font-smoothing: antialiased;
    transition: transform 0.45s var(--htb-spring), opacity 0.3s var(--htb-ease);
}

body.view-home-active .home-tabbar {
    display: flex;
}

body.rank-modal-open .home-tabbar,
.home-tabbar.htb-hidden {
    transform: translate(-50%, 140%);
    opacity: 0;
    pointer-events: none;
}

.home-tabbar * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    -webkit-tap-highlight-color: transparent;
}

.home-tabbar .htb-glass {
    position: absolute;
    inset: 0;
    border-radius: inherit;
    pointer-events: none;
    overflow: hidden;
    -webkit-backdrop-filter: blur(18px) saturate(165%) brightness(1.04);
    backdrop-filter: blur(18px) saturate(165%) brightness(1.04);
    background: rgba(255, 255, 255, var(--htb-veil));
    box-shadow:
        inset 0 0.75px 0 rgba(255, 255, 255, 0.95),
        inset 0 -0.5px 0 rgba(255, 255, 255, 0.28),
        0 0 0 0.5px rgba(15, 23, 42, 0.07),
        0 1px 1.5px rgba(15, 23, 42, 0.05),
        0 12px 30px -12px rgba(15, 23, 42, var(--htb-sh));
    transition: background 0.45s var(--htb-ease), box-shadow 0.45s var(--htb-ease);
}

.home-tabbar .htb-glass::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: radial-gradient(
        70% 120% at var(--hx) -55%,
        rgba(255, 255, 255, 0.55),
        rgba(255, 255, 255, 0) 60%
    );
    transition: opacity 0.45s;
}

.home-tabbar .htb-glass::after {
    content: "";
    position: absolute;
    left: 16px;
    right: 16px;
    top: 0;
    height: 1px;
    border-radius: 1px;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.95) var(--hx), transparent);
    opacity: 0.9;
}

.home-tabbar .htb-pill {
    position: absolute;
    top: 4px;
    left: 0;
    width: 0;
    height: 40px;
    border-radius: 999px;
    pointer-events: none;
    z-index: 1;
    -webkit-backdrop-filter: brightness(1.12) saturate(115%);
    backdrop-filter: brightness(1.12) saturate(115%);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.48));
    box-shadow:
        inset 0 0.75px 0 rgba(255, 255, 255, 0.98),
        inset 0 -0.5px 0 rgba(255, 255, 255, 0.55),
        inset 0 0 0 0.5px rgba(255, 255, 255, 0.55),
        0 0 0 0.5px rgba(15, 23, 42, 0.06),
        0 3px 10px -4px rgba(15, 23, 42, 0.18);
    transition: transform 0.55s var(--htb-spring), width 0.55s var(--htb-spring), background 0.45s, box-shadow 0.45s;
}

.home-tabbar.is-dragging .htb-pill {
    transition: width 0.3s var(--htb-spring);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.44), rgba(255, 255, 255, 0.2));
    box-shadow:
        inset 0 1px 0 #fff,
        inset 0 0 0 0.75px rgba(255, 255, 255, 0.75),
        0 0 0 0.5px rgba(15, 23, 42, 0.06),
        0 12px 26px -10px rgba(15, 23, 42, 0.3);
}

.home-tabbar .htb-tab {
    position: relative;
    z-index: 2;
    height: 40px;
    min-width: 49px;
    padding: 0 13px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 0;
    background: none;
    border-radius: 999px;
    cursor: pointer;
    font: inherit;
    color: rgba(15, 23, 42, 0.72);
    transition: color 0.35s, padding 0.55s var(--htb-spring);
}

.home-tabbar .htb-tab.on,
.home-tabbar .htb-tab.hov {
    color: #0b1220;
}

.home-tabbar .htb-tab.on {
    padding: 0 15px 0 13px;
}

.home-tabbar .htb-tab:focus-visible {
    outline: 2px solid rgba(10, 132, 255, 0.6);
    outline-offset: -2px;
}

.home-tabbar .htb-ico,
.home-tabbar .htb-tab span {
    filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0.75))
        drop-shadow(0 0 1px rgba(255, 255, 255, 0.6));
    transition: filter 0.35s;
}

.home-tabbar .htb-tab span {
    display: block;
    max-width: 0;
    opacity: 0;
    overflow: hidden;
    white-space: nowrap;
    font-size: 12.5px;
    font-weight: 650;
    letter-spacing: 0.02em;
    line-height: 1.25;
    padding-block: 1px;
    transform: translateX(-4px);
    transition: max-width 0.55s var(--htb-spring), opacity 0.25s, margin 0.55s var(--htb-spring), transform 0.45s var(--htb-ease), filter 0.35s;
}

.home-tabbar .htb-tab.on span {
    max-width: 42px;
    opacity: 1;
    margin-left: 6px;
    transform: none;
    transition-delay: 0s, 0.1s, 0s, 0.06s, 0s;
}

.home-tabbar .htb-ico {
    width: 20px;
    height: 20px;
    flex-shrink: 0;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.58;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.home-tabbar .htb-tab.on .htb-ico {
    stroke-width: 1.72;
    animation: htbPop 0.5s var(--htb-spring);
}

@keyframes htbPop {
    0% { transform: scale(0.82); }
    60% { transform: scale(1.06); }
    100% { transform: none; }
}

.home-tabbar:active:not(.is-dragging) {
    transform: translateX(-50%) scale(0.985);
}

/* Adaptive background contrast classes (1:1 LiquidGlassTabBar.vue) */
.home-tabbar .htb-tab.inv {
    color: rgba(255, 255, 255, 0.86);
}
.home-tabbar .htb-tab.inv.on,
.home-tabbar .htb-tab.inv.hov {
    color: #fff;
}
.home-tabbar .htb-tab.inv .htb-ico,
.home-tabbar .htb-tab.inv span {
    filter: drop-shadow(0 0 3px rgba(0, 0, 0, 0.45));
}

.home-tabbar.htb-dark {
    --htb-veil: 0;
    --htb-sh: 0.55;
}
.home-tabbar.htb-dark .htb-glass {
    background: rgba(19, 27, 43, 0.72);
    box-shadow:
        inset 0 0.75px 0 rgba(255, 255, 255, 0.24),
        inset 0 -0.5px 0 rgba(255, 255, 255, 0.06),
        0 0 0 0.5px rgba(148, 163, 184, 0.16),
        0 12px 30px -12px rgba(2, 6, 23, 0.68);
}
.home-tabbar.htb-dark .htb-glass::before { opacity: 0.35; }
.home-tabbar.htb-dark .htb-glass::after { opacity: 0.4; }
.home-tabbar.htb-dark .htb-pill {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.24), rgba(255, 255, 255, 0.1));
    box-shadow:
        inset 0 0.75px 0 rgba(255, 255, 255, 0.5),
        inset 0 0 0 0.5px rgba(255, 255, 255, 0.16),
        0 4px 12px -4px rgba(0, 0, 0, 0.4);
}
.home-tabbar.htb-dark .htb-tab { color: rgba(255, 255, 255, 0.78); }
.home-tabbar.htb-dark .htb-tab.on,
.home-tabbar.htb-dark .htb-tab.hov { color: #fff; }
.home-tabbar.htb-dark .htb-ico,
.home-tabbar.htb-dark .htb-tab span { filter: drop-shadow(0 0 3px rgba(0, 0, 0, 0.4)); }

.home-tabbar.htb-busy:not(.htb-dark) {
    --htb-veil: 0.66;
    --htb-sh: 0.34;
}
.home-tabbar.htb-white:not(.htb-dark):not(.htb-busy) {
    --htb-sh: 0.18;
}

@media (hover: hover) and (pointer: fine) {
    .home-tabbar .htb-tab:not(.on):hover {
        color: #0b1220;
        background: rgba(255, 255, 255, 0.32);
    }
    .home-tabbar.htb-dark .htb-tab:not(.on):hover {
        color: #fff;
        background: rgba(255, 255, 255, 0.08);
    }
}

@media (min-width: 768px) {
    body.is-tablet-device .home-tabbar,
    body.is-landscape .home-tabbar {
        height: 52px;
        padding: 5px;
        bottom: calc(18px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px)));
    }
    body.is-tablet-device .home-tabbar .htb-pill,
    body.is-landscape .home-tabbar .htb-pill {
        top: 5px;
        height: 42px;
    }
    body.is-tablet-device .home-tabbar .htb-tab,
    body.is-landscape .home-tabbar .htb-tab {
        height: 42px;
        min-width: 52px;
        padding: 0 15px;
    }
    body.is-tablet-device .home-tabbar .htb-tab.on,
    body.is-landscape .home-tabbar .htb-tab.on {
        padding: 0 17px 0 15px;
    }
}

@media (orientation: landscape) and (max-height: 520px) {
    .home-tabbar {
        height: 42px;
        padding: 4px;
        bottom: max(6px, var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px));
    }
    .home-tabbar .htb-pill { top: 4px; height: 34px; }
    .home-tabbar .htb-tab { height: 34px; min-width: 44px; padding: 0 11px; }
    .home-tabbar .htb-tab.on { padding: 0 13px 0 11px; }
}

/* Leave comfortable clearance under Home bottom sheet for the floating tab bar */
#view-home .home-bottom-sheet {
    padding-bottom: calc(92px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px))) !important;
}

/* -------------------------------------------------------------------------
   2. Tab Page Shell (统计 / 我的)
   ------------------------------------------------------------------------- */
.home-tab-panel {
    --tp-page: #ffffff;
    --tp-card: #ffffff;
    --tp-ink: #0b1220;
    --tp-ink2: #2b3445;
    --tp-sub: #7b8494;
    --tp-faint: #9aa2af;
    --tp-line: rgba(15, 23, 42, 0.06);
    --tp-track: #f1f3f6;
    --tp-soft: #f5f6f9;
    --tp-q1: #e3eee7;
    --tp-q2: #bfd9c9;
    --tp-q3: #8fc0a2;
    --tp-hi: #1e7a4c;
    --tp-bad: #d9534f;
    --tp-btn: #0b1220;
    --tp-e: cubic-bezier(0.2, 0.8, 0.2, 1);
    --tp-spring: cubic-bezier(0.34, 1.4, 0.5, 1);
    --tp-card-sh: 0 10px 32px rgba(15, 23, 42, 0.055), 0 2px 8px rgba(15, 23, 42, 0.025);
    position: fixed;
    inset: 0;
    z-index: 115;
    display: none;
    flex-direction: column;
    background: var(--tp-page);
    color: var(--tp-ink);
    opacity: 0;
    visibility: hidden;
    transform: translate3d(0, 8px, 0);
    pointer-events: none;
    overflow: hidden;
    transition: opacity 0.2s var(--tp-e), transform 0.28s var(--tp-e), visibility 0s linear 0.28s;
}

body.view-home-active .home-tab-panel {
    display: flex;
}

.home-tab-panel.is-open {
    opacity: 1;
    visibility: visible;
    transform: none;
    pointer-events: auto;
    transition: opacity 0.2s var(--tp-e), transform 0.28s var(--tp-e), visibility 0s linear 0s;
}

/* PC Desktop iPhone 16 Pro Frame seamless inset containment */
@media (min-width: 640px) {
    body.view-home-active:not(.is-landscape):not(.is-tablet-device) .home-tab-panel,
    body.view-home-active.is-pc-device .home-tab-panel {
        position: absolute !important;
        inset: 0 !important;
        width: 100% !important;
        height: 100% !important;
        border-radius: 44px !important;
    }
    body.view-home-active:not(.is-landscape):not(.is-tablet-device) .home-tabbar,
    body.view-home-active.is-pc-device .home-tabbar {
        position: absolute !important;
        bottom: 16px !important;
    }
}

/* Strictly scope home tab scroll lock so functional views are never affected */
body.view-home-active.home-tab-locked,
body.view-home-active.home-tab-locked .views-container {
    overflow: hidden !important;
}

.home-tab-panel * {
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
}

.home-tab-panel button {
    font: inherit;
    color: inherit;
    background: none;
    border: 0;
    cursor: pointer;
}

.htp-scroll {
    flex: 1;
    min-height: 0;
    width: 100%;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
    padding:
        calc(max(var(--toy-safe-top, 0px), env(safe-area-inset-top, 0px), 12px) + 6px)
        16px
        calc(112px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px)));
}

.htp-scroll::-webkit-scrollbar {
    display: none;
}

.htp-inner {
    width: 100%;
    max-width: 520px;
    margin: 0 auto;
}

.htp-nav {
    display: grid;
    grid-template-columns: 40px 1fr 40px;
    align-items: center;
    height: 44px;
    margin: 0 0 14px;
    padding: 0 4px;
}

.htp-nav h1 {
    margin: 0;
    text-align: center;
    font-size: 17px;
    font-weight: 800;
    letter-spacing: -0.01em;
    line-height: 1;
    color: #0f172a;
}

.htp-cb {
    position: relative;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: #f2f4f7 !important;
    color: #0f172a;
    flex-shrink: 0;
    transition: transform 0.2s var(--tp-spring), background-color 0.2s;
}

.htp-cb:active { transform: scale(0.92); }
.htp-cb svg { stroke: #0f172a; }

.htp-rv {
    opacity: 0;
    transform: translateY(14px);
}

.home-tab-panel.is-open .htp-rv {
    animation: htpReveal 0.55s var(--tp-e) forwards;
    animation-delay: calc(var(--rv-i, 0) * 60ms);
}

@keyframes htpReveal {
    to { opacity: 1; transform: none; }
}

.htp-toast {
    position: fixed;
    left: 50%;
    bottom: calc(80px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px)));
    transform: translate(-50%, 16px);
    background: #0b1220;
    color: #fff;
    font-size: 13px;
    font-weight: 700;
    padding: 10px 16px;
    border-radius: 999px;
    opacity: 0;
    transition: 0.3s;
    z-index: 130;
    white-space: nowrap;
    pointer-events: none;
}

.htp-toast.on {
    opacity: 1;
    transform: translate(-50%, 0);
}

/* Shared segmented control (1:1 IosSegmentedControl.vue + StudyStatsModal range) */
.htp-seg {
    position: relative;
    display: grid;
    grid-template-columns: repeat(var(--seg-n, 2), minmax(0, 1fr));
    align-items: center;
    background: #f2f5f9;
    border: 1px solid rgba(226, 232, 240, 0.9);
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.03);
    border-radius: 999px;
    padding: 3px;
    user-select: none;
}

.htp-seg .htp-seg-knob {
    position: absolute;
    top: 3px;
    bottom: 3px;
    left: 3px;
    width: calc((100% - 6px) / var(--seg-n, 2));
    border-radius: 999px;
    background: #ffffff;
    border: 1px solid rgba(226, 232, 240, 0.8);
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.08), 0 1px 2px rgba(15, 23, 42, 0.04);
    transform: translateX(calc(var(--seg-i, 0) * 100%));
    transition: transform 0.34s cubic-bezier(0.2, 0.85, 0.32, 1.05);
    pointer-events: none;
}

.htp-seg button {
    position: relative;
    z-index: 1;
    min-width: 52px;
    height: 30px;
    padding: 0 10px;
    border-radius: 999px;
    font-size: 12.5px;
    font-weight: 600;
    color: #64748b;
    white-space: nowrap;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: color 0.22s;
}

.htp-seg button.on {
    color: #0f172a;
    font-weight: 800;
}

.htp-seg.is-small button {
    min-width: 48px;
    height: 24px;
    padding: 0 10px;
    font-size: 12px;
}

/* -------------------------------------------------------------------------
   3. 统计 · 学习复盘
   ------------------------------------------------------------------------- */
.tps-range-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 4px;
}

.tps-range-bar .htp-seg {
    flex: 1;
    background: var(--tp-soft);
    border: 0;
    box-shadow: none;
}

.tps-flat {
    padding: 0 20px;
}

.tps-hero {
    margin-top: 24px;
}

.tps-hero .tps-lead {
    font-size: 15px;
    font-weight: 600;
    color: var(--tp-sub);
}

.tps-hero .tps-big {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-top: 12px;
}

.tps-hero .tps-big b {
    font-size: var(--hs, 72px);
    font-weight: 800;
    letter-spacing: -0.05em;
    line-height: 1;
    color: var(--tp-hi);
    font-variant-numeric: tabular-nums;
    transition: font-size 0.35s var(--tp-e);
}

.tps-hero .tps-big span {
    font-size: 22px;
    font-weight: 700;
    color: var(--tp-ink2);
}

.tps-hero .tps-delta {
    margin-top: 12px;
    font-size: 13px;
    font-weight: 600;
    color: var(--tp-sub);
}

.tps-hero .tps-delta b {
    font-weight: 800;
    color: var(--tp-ink);
}

.tps-hero .tps-delta b.dn {
    color: var(--tp-bad);
}

.tps-kpi {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 32px;
}

.tps-kpi .tps-m { min-width: 0; }

.tps-kpi .tps-v {
    display: flex;
    align-items: baseline;
    gap: 4px;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -0.03em;
    line-height: 1;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

.tps-kpi .tps-v .u {
    font-size: 13px;
    font-weight: 600;
    color: var(--tp-sub);
    letter-spacing: 0;
}

.tps-kpi .tps-c {
    margin-top: 8px;
    font-size: 13px;
    font-weight: 500;
    color: var(--tp-sub);
    white-space: nowrap;
}

.tps-sec {
    margin-top: 40px;
}

.tps-hd {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    min-height: 28px;
}

.tps-hd h3 {
    margin: 0;
    font-size: 17px;
    font-weight: 800;
    letter-spacing: -0.01em;
    line-height: 1.3;
    white-space: nowrap;
}

.tps-hd .tps-meta {
    font-size: 13px;
    font-weight: 500;
    color: var(--tp-sub);
    white-space: nowrap;
}

.tps-hd .tps-meta b {
    color: var(--tp-ink2);
    font-weight: 700;
}

.tps-trend {
    position: relative;
    height: 136px;
    display: flex;
    align-items: flex-end;
    gap: var(--gap, 8px);
    margin-top: 24px;
}

.tps-trend .tps-b {
    flex: 1;
    height: 100%;
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    align-items: center;
    position: relative;
    cursor: pointer;
}

.tps-trend .tps-b i {
    display: block;
    width: 100%;
    max-width: 22px;
    height: 0;
    border-radius: 6px 6px 2px 2px;
    background: var(--tp-q1);
    transition: height 0.7s var(--tp-e), background-color 0.3s;
}

.tps-trend .tps-b.peak i,
.tps-trend .tps-b.sel i {
    background: var(--tp-hi);
}

.tps-trend .tps-b.zero i {
    background: var(--tp-track);
}

.tps-tipb {
    position: absolute;
    bottom: calc(var(--h) + 6px);
    left: 50%;
    transform: translateX(-50%);
    background: var(--tp-btn);
    color: #fff;
    font-size: 12px;
    font-weight: 700;
    padding: 4px 8px;
    border-radius: 8px;
    white-space: nowrap;
    opacity: 0;
    pointer-events: none;
    z-index: 2;
    transition: opacity 0.2s;
}

.tps-b.sel .tps-tipb { opacity: 1; }
.tps-b.edgeL .tps-tipb { left: 0; transform: none; }
.tps-b.edgeR .tps-tipb { left: auto; right: 0; transform: none; }

.tps-xl {
    display: flex;
    gap: var(--gap, 8px);
    margin-top: 8px;
}

.tps-xl span {
    flex: 1;
    min-width: 0;
    display: flex;
    justify-content: center;
    font-size: 12px;
    font-weight: 500;
    color: var(--tp-faint);
    white-space: nowrap;
}

.tps-hw { position: relative; }

.tps-heat {
    display: grid;
    grid-template-columns: repeat(16, 1fr);
    grid-template-rows: repeat(7, auto);
    grid-auto-flow: column;
    gap: 4px;
    margin-top: 20px;
}

.tps-heat i {
    display: block;
    aspect-ratio: 1;
    border-radius: 4px;
    background: var(--tp-track);
    cursor: pointer;
    transform: scale(0.5);
    opacity: 0;
    transition: transform 0.45s var(--tp-spring), opacity 0.3s, background-color 0.5s;
}

.tps-heat.show i {
    transform: none;
    opacity: 1;
}

.tps-heat i.l1 { background: var(--tp-q1); }
.tps-heat i.l2 { background: var(--tp-q2); }
.tps-heat i.l3 { background: var(--tp-q3); }
.tps-heat i.today { background: var(--tp-hi); }
.tps-heat i.fut { background: transparent; box-shadow: inset 0 0 0 1px var(--tp-line); cursor: default; }
.tps-heat i.pick { outline: 2px solid var(--tp-ink); outline-offset: 1px; }

.tps-htip {
    position: absolute;
    z-index: 3;
    transform: translate(-50%, -100%);
    background: var(--tp-btn);
    color: #fff;
    font-size: 12px;
    font-weight: 700;
    padding: 6px 10px;
    border-radius: 8px;
    white-space: nowrap;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.15s;
}

.tps-htip.on { opacity: 1; }

/* -------------------------------------------------------------------------
   3B. 练习构成（分段比例条 + 4 项极简明细）
   ------------------------------------------------------------------------- */
.tps-comp-bar {
    display: flex;
    align-items: stretch;
    gap: 3px;
    height: 10px;
    margin-top: 16px;
    border-radius: 999px;
    background: var(--tp-track);
    overflow: hidden;
}

.tps-comp-seg {
    display: block;
    height: 100%;
    min-width: 6px;
    border-radius: 3px;
    transform: scaleX(0.2);
    transform-origin: left center;
    opacity: 0;
    transition: transform 0.55s var(--tp-e), opacity 0.3s;
}

.tps-comp-bar.show .tps-comp-seg {
    transform: none;
    opacity: 1;
}

.tps-comp-seg.is-listen,
.tps-comp-dot.is-listen { background: #1e7a4c; }

.tps-comp-seg.is-written,
.tps-comp-dot.is-written { background: #3b6e8c; }

.tps-comp-seg.is-dict,
.tps-comp-dot.is-dict { background: #68a684; }

.tps-comp-seg.is-vocab,
.tps-comp-dot.is-vocab { background: #d4943a; }

.tps-comp-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px 20px;
    margin-top: 18px;
}

.tps-comp-item {
    min-width: 0;
}

.tps-comp-lbl {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 600;
    color: var(--tp-sub);
    white-space: nowrap;
}

.tps-comp-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    flex-shrink: 0;
}

.tps-comp-val {
    display: flex;
    align-items: baseline;
    gap: 4px;
    margin-top: 6px;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

.tps-comp-val b {
    font-size: 20px;
    font-weight: 800;
    letter-spacing: -0.03em;
    line-height: 1;
    color: var(--tp-ink);
}

.tps-comp-val .u {
    font-size: 12.5px;
    font-weight: 600;
    color: var(--tp-sub);
}

.tps-comp-acc {
    margin-left: 6px;
    font-style: normal;
    font-size: 11.5px;
    font-weight: 600;
    color: var(--tp-faint);
}

@media (max-width: 374px) {
    .htp-scroll {
        padding-left: 12px;
        padding-right: 12px;
    }
    .tps-comp-grid {
        gap: 14px 12px;
    }
    .tps-comp-acc {
        margin-left: 4px;
        font-size: 11px;
    }
}

/* -------------------------------------------------------------------------
   4. Responsive: tablet / desktop wide
   ------------------------------------------------------------------------- */
@media (hover: hover) and (pointer: fine) {
    .tps-trend .tps-b:not(.zero):hover i {
        filter: brightness(0.94);
        transform: scaleY(1.02);
        transform-origin: bottom;
    }
    .tps-trend .tps-b:not(.zero):hover .tps-tipb {
        opacity: 1;
    }
    .tps-heat i:not(.fut):hover {
        transform: scale(1.14);
        z-index: 2;
    }
    .htp-cb:hover {
        background: #e9edf3 !important;
        transform: translateY(-1px);
    }
}

@media (min-width: 640px) {
    body.is-landscape .htp-inner,
    body.is-tablet-device .htp-inner {
        max-width: 680px;
    }
    body.is-landscape .tps-trend,
    body.is-tablet-device .tps-trend {
        height: 164px;
    }
    body.is-landscape .tps-trend .tps-b i,
    body.is-tablet-device .tps-trend .tps-b i {
        max-width: 28px;
    }
    body.is-landscape .tps-comp-grid,
    body.is-tablet-device .tps-comp-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
}

@media (prefers-reduced-motion: reduce) {
    .home-tabbar,
    .home-tabbar *,
    .home-tab-panel,
    .home-tab-panel * {
        transition: none !important;
        animation: none !important;
    }
    .home-tab-panel .htp-rv {
        opacity: 1;
        transform: none;
    }
}

@media (prefers-reduced-transparency: reduce) {
    .home-tabbar .htb-glass {
        background: rgba(250, 250, 252, 0.96) !important;
    }
}


/* === css/quiz.css === */
/* ==========================================================================
   Listening Quiz Arena System (Stage Card, Options, Explanation, Navigation)
   ========================================================================== */

#view-quiz {
    width: 100%;
    max-width: 880px;
    margin: 0 auto;
    padding-bottom: calc(115px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px)));
}

.quiz-stage-card {
    width: 100%;
    min-height: auto;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: visible;
    box-sizing: border-box;
    will-change: opacity, transform;
}

/* ✨ Apple iOS Card Glide Animations (切题前后平滑滑动，支持仅右栏/抽屉内题干选项滑动保持左文静止) */
.quiz-stage-card.card-slide-forward,
#written-stage-card.card-slide-forward,
.written-stage-card.card-slide-forward,
.written-split-quiz.card-slide-forward,
#written-q-h2.card-slide-forward,
#written-options-wrapper.card-slide-forward {
    animation: iosCardSlideForward 0.18s cubic-bezier(0.32, 0.72, 0, 1) backwards;
}

.quiz-stage-card.card-slide-backward,
#written-stage-card.card-slide-backward,
.written-stage-card.card-slide-backward,
.written-split-quiz.card-slide-backward,
#written-q-h2.card-slide-backward,
#written-options-wrapper.card-slide-backward {
    animation: iosCardSlideBackward 0.18s cubic-bezier(0.32, 0.72, 0, 1) backwards;
}

@keyframes iosCardSlideForward {
    0% {
        opacity: 0.76;
        transform: translate3d(12px, 0, 0);
    }
    100% {
        opacity: 1;
        transform: translate3d(0, 0, 0);
    }
}

@keyframes iosCardSlideBackward {
    0% {
        opacity: 0.76;
        transform: translate3d(-12px, 0, 0);
    }
    100% {
        opacity: 1;
        transform: translate3d(0, 0, 0);
    }
}

.quiz-card-inner {
    width: 100%;
    padding: 8px 2px 24px 2px;
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    gap: 14px;
}

/* Portrait Split Container: display:contents ensures natural Question -> Options -> Explanation order */
.quiz-split-container {
    display: flex;
    flex-direction: column;
    gap: 0;
    width: 100%;
}
.quiz-split-left,
.quiz-split-right {
    display: contents;
}

#quiz-stage-card .quiz-card-top-bar {
    order: 1;
    margin-bottom: 14px;
}
#quiz-stage-card .sequence-badge {
    display: none !important;
}
#quiz-stage-card .question-h2 {
    order: 2;
}
#quiz-stage-card .question-zh-p {
    order: 3;
}
#quiz-stage-card .options-wrapper {
    order: 4;
}
#quiz-stage-card .explanation-card {
    order: 5;
}

@media (min-width: 768px) {
    .quiz-card-inner {
        padding: 12px 6px 32px 6px;
        gap: 16px;
    }
}

.quiz-card-top-bar {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

.sequence-badge {
    display: inline-flex;
    align-items: center;
    background: #ffffff;
    border: var(--opt-border);
    border-radius: 999px;
    padding: 3px 4px 3px 12px;
    gap: 8px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03);
    margin: 0;
}
.seq-lbl {
    font-size: 11.5px;
    font-weight: 700;
    color: var(--ink-sub);
    letter-spacing: 0.04em;
}
.seq-val {
    background: var(--accent-gold);
    color: #ffffff;
    font-size: 13.5px;
    font-weight: 800;
    padding: 4px 11px;
    border-radius: 999px;
    letter-spacing: -0.01em;
}

.section-badge {
    font-size: 12.5px;
    font-weight: 600;
    color: var(--ink-sub);
    border: var(--opt-border);
    padding: 5px 14px;
    border-radius: 999px;
    letter-spacing: 0.01em;
    background: #ffffff;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.02);
    margin: 0;
}

/* Golden Ratio Question Stem & Bilingual Subtitle Pair */
.question-h2 {
    font-size: clamp(17.5px, 1.55vw, 20.5px);
    font-weight: 700;
    line-height: 1.55;
    color: var(--ink-primary);
    margin: 0;
    padding: 0;
    letter-spacing: -0.012em;
    word-spacing: normal;
    width: 100%;
}

.question-zh-p {
    font-size: clamp(14.5px, 1.25vw, 16.5px);
    font-weight: 500;
    color: var(--accent-gold);
    line-height: 1.62;
    margin: 8px 0 0 0;
    padding: 0;
    letter-spacing: 0.005em;
    display: none;
}
.question-zh-p.show {
    display: block;
}

.options-wrapper {
    display: flex;
    flex-direction: column;
    gap: 14px;
    width: 100%;
    margin: 18px 0 0 0;
    padding: 0;
    box-sizing: border-box;
}

.opt-btn {
    position: relative;
    display: flex;
    align-items: flex-start;
    padding: 15px 18px;
    border-radius: 16px;
    width: 100%;
    margin: 0;
    box-sizing: border-box;
    font-size: 15.5px;
    font-weight: 500;
    line-height: 1.62;
    letter-spacing: -0.005em;
    border: var(--opt-border);
    box-shadow: var(--opt-resting-shadow);
    cursor: pointer;
    transition: transform 0.14s var(--ios-press), background-color 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
    background-color: #ffffff;
    color: var(--ink-primary);
    text-align: left;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
    -webkit-user-select: none;
}
@media (max-width: 600px) {
    .opt-btn {
        padding: 13px 15px;
        border-radius: 14px;
    }
}
@media (hover: hover) and (pointer: fine) {
    .opt-btn:hover:not(.disabled) {
        transform: translateY(-1.5px);
        box-shadow: 0 5px 16px rgba(0, 122, 255, 0.075);
        border-color: rgba(0, 122, 255, 0.45);
        background-color: var(--accent-gold-light);
    }
}
.opt-btn:active:not(.disabled) {
    transform: scale(0.986) !important;
    background-color: rgba(15, 23, 42, 0.02);
}

.opt-key {
    font-weight: 700;
    color: var(--accent-gold);
    margin-right: 10px;
    font-size: 15.5px;
    line-height: 1.62;
    flex-shrink: 0;
}

.opt-text-col {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    flex: 1;
    min-width: 0;
    width: 100%;
    max-width: 100%;
}

.opt-en-text {
    font-size: 15.5px;
    font-weight: 500;
    line-height: 1.62;
    color: var(--ink-primary);
    display: inline;
    width: auto;
    background-image: linear-gradient(90deg, #94a3b8, #94a3b8);
    background-repeat: no-repeat;
    background-position: 100% 55%;
    background-size: 0% 1.6px;
    transition: background-size 0.22s cubic-bezier(0.22, 1, 0.36, 1), color 0.18s ease;
}

.opt-zh-text {
    font-size: 14px;
    font-weight: 400;
    color: #52525b !important;
    line-height: 1.65;
    letter-spacing: 0.01em;
    display: none;
    margin-top: 0;
    padding-top: 0;
    border-top: none !important;
    width: 100%;
}
.opt-zh-text.show {
    display: block;
}
.opt-zh-text.show::before {
    content: '';
    display: block;
    width: 100%;
    border-top: 1px dashed rgba(0, 0, 0, 0.08);
    margin: 10px 0 9px 0;
}

/* Option Feedback States - Refined Clean iOS Human Interface Guidelines */
.opt-btn:active {
    transform: scale(0.986) !important;
}

.opt-btn.correct-state {
    background-color: #f2faf5 !important;
    border-color: rgba(22, 163, 74, 0.32) !important;
    color: #166534 !important;
    animation: duo-pop-bounce 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    box-shadow: none !important;
}
.opt-btn.correct-state .opt-key { color: #15803d; font-weight: 700; }
.opt-btn.correct-state .opt-text,
.opt-btn.correct-state .opt-en-text { color: #166534 !important; font-weight: 600; }
.opt-btn.correct-state .opt-zh-text { color: #475569 !important; }

.opt-btn.wrong-state {
    background-color: #fdf3f3 !important;
    border-color: rgba(220, 38, 38, 0.28) !important;
    color: #991b1b !important;
    animation: duo-jelly-shake 0.20s cubic-bezier(0.25, 1, 0.5, 1);
    box-shadow: none !important;
}
.opt-btn.wrong-state .opt-key { color: #b91c1c; font-weight: 700; }
.opt-btn.wrong-state .opt-text,
.opt-btn.wrong-state .opt-en-text { color: #991b1b !important; font-weight: 600; }
.opt-btn.wrong-state .opt-zh-text { color: #475569 !important; }

.opt-btn.disabled {
    cursor: pointer !important;
}

/* Exam Simulation Selected Option Pill */
.opt-btn.exam-selected-state {
    background: rgba(0, 122, 255, 0.10) !important;
    border-color: #007aff !important;
    color: #007aff !important;
    font-weight: 600;
}
.opt-btn.exam-selected-state .opt-key {
    color: #007aff;
    font-weight: 700;
}
.opt-btn.exam-selected-state .opt-text,
.opt-btn.exam-selected-state .opt-en-text {
    color: #007aff !important;
    font-weight: 600;
}
.opt-btn.exam-selected-state .opt-zh-text {
    color: #636366 !important;
}

/* ==========================================================================
   Silky-Smooth Option Elimination & One-Tap Restoration System
   ========================================================================== */
.opt-btn,
.word-bank-opt-btn {
    position: relative;
}

.opt-btn.opt-eliminated:not(.correct-state):not(.wrong-state):not(.exam-selected-state),
.word-bank-opt-btn.opt-eliminated:not(.correct-state):not(.wrong-state):not(.exam-selected-state) {
    background-color: rgba(248, 250, 252, 0.72) !important;
    border-color: rgba(148, 163, 184, 0.36) !important;
    border-style: dashed !important;
    box-shadow: none !important;
    transform: scale(0.992);
}

.opt-btn.opt-eliminated:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .opt-key,
.word-bank-opt-btn.opt-eliminated:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .word-bank-opt-key {
    color: #94a3b8 !important;
    opacity: 0.65;
    text-decoration: line-through;
}

.opt-btn.opt-eliminated:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .opt-en-text,
.word-bank-opt-btn.opt-eliminated:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .word-bank-opt-text {
    color: #94a3b8 !important;
    background-position: 0% 54%;
    background-size: 100% 1.6px;
}

.opt-btn.opt-eliminated:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .opt-zh-text {
    color: #94a3b8 !important;
    opacity: 0.65;
}

.word-bank-opt-btn .word-bank-opt-text {
    background-image: linear-gradient(90deg, #94a3b8, #94a3b8);
    background-repeat: no-repeat;
    background-position: 100% 54%;
    background-size: 0% 1.6px;
    transition: background-size 0.22s cubic-bezier(0.22, 1, 0.36, 1), color 0.18s ease;
}

/* 15选10 / 七选五 已在其他题号选过的选项自动弱化标记 */
.opt-btn.opt-used-elsewhere:not(.correct-state):not(.wrong-state):not(.exam-selected-state),
.word-bank-opt-btn.opt-used-elsewhere:not(.correct-state):not(.wrong-state):not(.exam-selected-state) {
    background-color: rgba(248, 250, 252, 0.72) !important;
    border-color: rgba(148, 163, 184, 0.32) !important;
    border-style: dashed !important;
    box-shadow: none !important;
}

.opt-btn.opt-used-elsewhere:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .opt-key,
.word-bank-opt-btn.opt-used-elsewhere:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .word-bank-opt-key {
    color: #94a3b8 !important;
    opacity: 0.65;
}

.opt-btn.opt-used-elsewhere:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .opt-en-text,
.word-bank-opt-btn.opt-used-elsewhere:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .word-bank-opt-text {
    color: #94a3b8 !important;
    background-position: 0% 54%;
    background-size: 100% 1.5px;
}

.opt-btn.opt-used-elsewhere:not(.correct-state):not(.wrong-state):not(.exam-selected-state) .opt-zh-text {
    color: #94a3b8 !important;
    opacity: 0.65;
}

.opt-used-badge {
    margin-left: auto;
    flex-shrink: 0;
    font-size: 11px;
    font-weight: 700;
    color: #64748b;
    background: rgba(148, 163, 184, 0.16);
    padding: 1.5px 6px;
    border-radius: 999px;
    line-height: 1.3;
    user-select: none;
}

/* 选词填空卡片右上角悬浮角标：零水平挤压、不抢占单词宽度 */
.word-bank-opt-btn .opt-used-badge {
    position: absolute;
    top: -7px;
    right: 7px;
    margin-left: 0;
    z-index: 2;
    font-size: 10px;
    font-weight: 700;
    color: #64748b;
    background: #f1f5f9;
    border: 1px solid rgba(148, 163, 184, 0.42);
    padding: 0.5px 5.5px;
    border-radius: 999px;
    line-height: 1.35;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
    pointer-events: none;
}

/* ==========================================================================
   Question Explanation Area - Editorial Streamlined (Plan A 杂志极简呼吸流)
   ========================================================================== */
.explanation-card {
    margin: 20px 0 0 0;
    padding: 22px 0 0 0;
    border-radius: 0 !important;
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    border-top: 1px solid rgba(0, 0, 0, 0.08) !important;
    box-shadow: none !important;
    width: 100%;
    box-sizing: border-box;
    display: none;
    animation: fadeInExp 0.25s ease-out;
}
.explanation-card.show {
    display: flex;
    flex-direction: column;
    gap: 16px;
}
.explanation-card > *:empty {
    display: none !important;
}
@keyframes fadeInExp {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
}

.exp-title-lbl {
    font-size: 14.5px;
    font-weight: 700;
    color: #111113;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    gap: 8px;
    letter-spacing: -0.01em;
}
.exp-body-p {
    font-size: 14.5px;
    line-height: 1.75;
    color: #2c2c2e;
    margin: 0;
}

/* Evidence Container - Apple Classic Minimal Quote Line */
.exp-evidence-box {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    border-left: 2.5px solid #007aff !important;
    border-radius: 0 !important;
    padding: 4px 0 4px 16px !important;
    margin: 4px 0 0 0 !important;
    display: flex;
    flex-direction: column;
    gap: 8px;
    box-shadow: none !important;
    transition: opacity 0.2s ease;
}
.exp-evidence-box:hover {
    opacity: 0.9;
}
.exp-evidence-lbl {
    font-size: 12px;
    font-weight: 700;
    color: #007aff;
    letter-spacing: 0.02em;
    display: flex;
    align-items: center;
    gap: 6px;
}
.exp-evidence-en {
    font-size: 14.5px;
    color: #111113;
    font-weight: 600;
    line-height: 1.62;
    margin: 0;
}
.exp-evidence-zh {
    font-size: 13.5px;
    color: #52525b;
    line-height: 1.65;
    margin: 2px 0 0 0;
}

/* Synonym Replacement - Clean Left-Aligned Quote Block (No Capsules) */
.exp-synonym-box {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    border-left: 2.5px solid #16a34a !important;
    border-radius: 0 !important;
    padding: 4px 0 4px 16px !important;
    margin: 4px 0 0 0 !important;
    display: flex;
    flex-direction: column;
    gap: 8px;
    box-shadow: none !important;
}
.exp-synonym-lbl {
    font-size: 12px;
    font-weight: 700;
    color: #15803d;
    letter-spacing: 0.02em;
    display: flex;
    align-items: center;
    gap: 6px;
}
.synonym-pair-item, .synonym-pair-row {
    font-size: 13.8px;
    color: #1c1c1e;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
    line-height: 1.55;
    padding: 2px 0;
}
.synonym-pair-item + .synonym-pair-item,
.synonym-pair-row + .synonym-pair-row {
    margin-top: 4px;
    padding-top: 6px;
    border-top: 1px dashed rgba(15, 23, 42, 0.08);
}
.syn-line {
    display: flex;
    align-items: baseline;
    gap: 8px;
    line-height: 1.55;
}
.syn-tag {
    font-size: 11.5px;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 4px;
    flex-shrink: 0;
    line-height: 1.4;
}
.syn-tag-q {
    color: #475569;
    background: #f1f5f9;
}
.syn-tag-orig {
    color: #166534;
    background: rgba(22, 163, 74, 0.10);
}
.syn-text-q {
    font-size: 13.8px;
    font-weight: 600;
    color: #334155;
    word-break: break-word;
}
.syn-text-orig {
    font-size: 13.8px;
    font-weight: 600;
    color: #166534;
    word-break: break-word;
}
.exp-analysis-seg {
    margin-bottom: 6px;
    line-height: 1.76;
}
.exp-analysis-seg:last-child {
    margin-bottom: 0;
}
.exp-opt-tag {
    font-weight: 700;
    color: #111827;
    margin-right: 2px;
}

/* Mobile Floating Pill to Return from Passage to Question */
.back-to-question-pill {
    position: fixed;
    bottom: calc(74px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px)));
    left: 50%;
    transform: translateX(-50%) translateY(16px);
    background: rgba(28, 28, 30, 0.90);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    color: #ffffff;
    font-size: 13px;
    font-weight: 600;
    padding: 8px 16px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
    z-index: 950;
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.22s ease, transform 0.22s ease;
    white-space: nowrap;
}
.back-to-question-pill.show {
    opacity: 1;
    pointer-events: auto;
    transform: translateX(-50%) translateY(0);
}

/* ==========================================================================
   iOS 26 Liquid Glass Floating Capsule Dock (1:1 单词Toy 液态玻璃规范)
   ========================================================================== */

.bottom-nav-bar {
    --lg-ease: cubic-bezier(0.32, 0.72, 0, 1);
    --lg-spring: cubic-bezier(0.3, 1.25, 0.45, 1);
    --hx: 50%;
    --veil: 0.30;
    --sh: 0.24;
    position: fixed;
    bottom: calc(16px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px)));
    left: 50%;
    transform: translateX(-50%);
    width: auto;
    max-width: calc(100% - 24px);
    height: 48px;
    padding: 4px;
    background: transparent !important;
    border: none !important;
    border-radius: 999px;
    box-shadow: none !important;
    z-index: 80;
    display: none;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    touch-action: manipulation;
    user-select: none;
    -webkit-user-select: none;
    -webkit-font-smoothing: antialiased;
    transition: transform 0.45s var(--lg-spring), opacity 0.3s var(--lg-ease);
}

.bottom-nav-bar .lg-glass {
    position: absolute;
    inset: 0;
    border-radius: inherit;
    pointer-events: none;
    overflow: hidden;
    z-index: 0;
    -webkit-backdrop-filter: blur(12px) saturate(150%) brightness(1.04);
    backdrop-filter: blur(12px) saturate(150%) brightness(1.04);
    background: rgba(255, 255, 255, var(--veil));
    box-shadow:
        inset 0 0.75px 0 rgba(255, 255, 255, 0.95),
        inset 0 -0.5px 0 rgba(255, 255, 255, 0.28),
        0 0 0 0.5px rgba(15, 23, 42, 0.07),
        0 1px 1.5px rgba(15, 23, 42, 0.05),
        0 12px 30px -12px rgba(15, 23, 42, var(--sh));
    transition: background 0.45s var(--lg-ease), box-shadow 0.45s var(--lg-ease);
}

.bottom-nav-bar .lg-glass::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: radial-gradient(
        70% 120% at var(--hx) -55%,
        rgba(255, 255, 255, 0.55),
        rgba(255, 255, 255, 0) 60%
    );
    transition: opacity 0.45s;
}

.bottom-nav-bar .lg-glass::after {
    content: "";
    position: absolute;
    left: 16px;
    right: 16px;
    top: 0;
    height: 1px;
    border-radius: 1px;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.95) var(--hx), transparent);
    opacity: 0.9;
}

/* 自适应背景感知：下方滚动经过文字/密集卡片时适度增强遮罩与阴影 */
.bottom-nav-bar.lg-busy {
    --veil: 0.46;
    --sh: 0.34;
}

.bottom-nav-bar.lg-white:not(.lg-busy) {
    --sh: 0.18;
}

.nav-btn-group {
    position: relative;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 2px;
    width: auto;
}

/* 一体化液态玻璃舱内按钮：两侧无框融入玻璃底座，中央胶囊为折射内透镜 */
.btn-nav-action {
    position: relative;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 40px;
    padding: 0 16px;
    border-radius: 999px;
    border: none;
    font-size: 13px;
    font-weight: 650;
    letter-spacing: -0.01em;
    cursor: pointer;
    background: transparent;
    color: rgba(15, 23, 42, 0.82);
    box-shadow: none;
    filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0.75))
            drop-shadow(0 0 1px rgba(255, 255, 255, 0.6));
    transition: transform 0.16s var(--ios-press), color 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
    white-space: nowrap;
    user-select: none;
    -webkit-tap-highlight-color: transparent;
}

/* 中央悬浮液态玻璃内胶囊 (选句清单 / 答题卡) & 桌面端按钮悬停态 */
.btn-nav-action.lg-pill-btn {
    color: #0b1220;
    -webkit-backdrop-filter: brightness(1.12) saturate(115%);
    backdrop-filter: brightness(1.12) saturate(115%);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.34));
    box-shadow:
        inset 0 0.75px 0 rgba(255, 255, 255, 0.98),
        inset 0 -0.5px 0 rgba(255, 255, 255, 0.55),
        inset 0 0 0 0.5px rgba(255, 255, 255, 0.5),
        0 0 0 0.5px rgba(15, 23, 42, 0.06),
        0 3px 10px -4px rgba(15, 23, 42, 0.16);
}

@media (hover: hover) and (pointer: fine) {
    .btn-nav-action:hover:not(:disabled) {
        color: #0b1220;
        -webkit-backdrop-filter: brightness(1.12) saturate(115%);
        backdrop-filter: brightness(1.12) saturate(115%);
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.34));
        box-shadow:
            inset 0 0.75px 0 rgba(255, 255, 255, 0.98),
            inset 0 -0.5px 0 rgba(255, 255, 255, 0.55),
            inset 0 0 0 0.5px rgba(255, 255, 255, 0.5),
            0 0 0 0.5px rgba(15, 23, 42, 0.06),
            0 3px 10px -4px rgba(15, 23, 42, 0.16);
    }
    .btn-nav-action.lg-pill-btn:hover:not(:disabled) {
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.74), rgba(255, 255, 255, 0.44));
        transform: translateY(-0.5px);
    }
}

.btn-nav-action:active:not(:disabled) {
    transform: scale(0.95);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.44), rgba(255, 255, 255, 0.20));
    box-shadow:
        inset 0 1px 0 #ffffff,
        inset 0 0 0 0.75px rgba(255, 255, 255, 0.75),
        0 0 0 0.5px rgba(15, 23, 42, 0.06),
        0 8px 20px -8px rgba(15, 23, 42, 0.24);
}

/* Progress counter pill inside drawer button */
.btn-nav-action span {
    background: rgba(15, 23, 42, 0.06);
    border: 0.5px solid rgba(255, 255, 255, 0.65);
    color: #0b1220;
    padding: 1px 7px;
    border-radius: 999px;
    font-size: 11.5px;
    font-weight: 700;
    margin-left: 5px;
}

/* Disabled State */
.btn-nav-action:disabled {
    opacity: 0.32;
    cursor: not-allowed;
    background: transparent !important;
    transform: none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

.btn-redo-single {
    background: rgba(0, 0, 0, 0.05);
    border: 1px solid rgba(0, 0, 0, 0.1);
    color: var(--ink-sub);
    font-size: 12px;
    font-weight: 700;
    padding: 5px 14px;
    border-radius: 999px;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
}
.btn-redo-single:hover {
    background: #1c1c1e;
    color: #ffffff;
    border-color: #1c1c1e;
}

/* ==========================================================================
   🔔 Option Micro-Animations
   ========================================================================== */

@keyframes duo-pop-bounce {
    0% { transform: scale(0.96); }
    45% { transform: scale(1.035); }
    100% { transform: scale(1); }
}

@keyframes duo-jelly-shake {
    0% { transform: translateX(0); }
    30% { transform: translateX(-2.5px); }
    70% { transform: translateX(1.5px); }
    100% { transform: translateX(0); }
}



/* === css/written.css === */
/* ==========================================================================
   Written Exam Arena System (Cloze, Matching, Reading, Translation, Writing)
   ========================================================================== */

#view-written-arena {
