    text-align: left;
    word-spacing: normal;
    letter-spacing: normal;
}
.written-passage-card p:last-child {
    margin-bottom: 0;
}

/* 原文定位证据句高亮系统 (Apple Books Soft Highlighter + TOP 2 RoughNotation SVG Hand-Drawn Pen) */
mark.passage-evidence-highlight {
    background: rgba(2, 132, 199, 0.10);
    color: inherit;
    border-bottom: none;
    border-radius: 4px;
    padding: 2px 2px;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
    transition: background-color 0.3s ease, box-shadow 0.3s ease;
}
@keyframes uxRoughDraw {
    to {
        stroke-dashoffset: 0;
    }
}
mark.passage-evidence-highlight.evidence-pulse {
    animation: evidenceHighlightPulse 1.5s cubic-bezier(0.25, 1, 0.5, 1);
}
@keyframes evidenceHighlightPulse {
    0%, 100% {
        background: rgba(2, 132, 199, 0.11);
        box-shadow: none;
    }
    35% {
        background: rgba(2, 132, 199, 0.26);
        box-shadow: 0 0 0 3px rgba(2, 132, 199, 0.14);
    }
}
.passage-evidence-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: 800;
    color: #FFFFFF;
    background: #0284C7;
    padding: 1px 7px;
    border-radius: 999px;
    margin-right: 5px;
    vertical-align: middle;
    line-height: 1.4;
    text-indent: 0 !important;
    user-select: none;
    box-shadow: 0 1px 3px rgba(2, 132, 199, 0.25);
}

/* ==========================================================================
   用户自主画线定位系统 (无背景污染 · 极简钢笔下划线 · 横划即画 / 轻点即擦)
   ========================================================================== */
.written-passage-card {
    position: relative;
    user-select: none;
    -webkit-user-select: none;
    -webkit-touch-callout: none;
}

.written-passage-card .dict-word,
.written-passage-card .dict-sep {
    padding-bottom: 2px;
    background-image: linear-gradient(90deg, rgba(37, 99, 235, 0.76), rgba(37, 99, 235, 0.76));
    background-repeat: no-repeat;
    background-position: 100% 100%;
    background-size: 0% 1.8px;
    transition: background-size 0.22s cubic-bezier(0.22, 1, 0.36, 1), color 0.16s ease;
}

.written-passage-card .dict-word.is-user-underlined,
.written-passage-card .dict-sep.is-user-underlined {
    background-position: 0% 100%;
    background-size: 100% 1.8px;
    cursor: pointer;
}

.popover-underline-btn {
    margin-left: auto;
    display: inline-flex;
    align-items: center;
    gap: 3px;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: 999px;
    cursor: pointer;
    border: 1px solid rgba(147, 197, 253, 0.42);
    background: rgba(59, 130, 246, 0.18);
    color: #bfdbfe;
    white-space: nowrap;
