}

/* Cloze Blanks Pill Tags (iOS Minimalist Flat Style) */
.written-cloze-blank {
    display: inline-block;
    vertical-align: baseline;
    text-indent: 0 !important;
    text-align: center;
    padding: 1px 9px;
    margin: 0 2px;
    border: none !important;
    background: rgba(0, 122, 255, 0.09);
    color: #007AFF;
    font-weight: 600;
    border-radius: 6px;
    cursor: pointer;
    box-shadow: none !important;
    line-height: 1.4;
    white-space: nowrap;
    transition: all 0.18s ease;
}
.written-cloze-blank.active {
    background: #007AFF !important;
    color: #FFFFFF !important;
    font-weight: 600;
    border: none !important;
    box-shadow: none !important;
    text-indent: 0 !important;
    outline: none;
}
.written-cloze-blank.filled-correct,
.written-cloze-blank.active.filled-correct {
