    box-shadow: none !important;
    color: #007AFF !important;
}
.written-cloze-blank.active.filled-correct,
.written-cloze-blank.active.filled-wrong,
.written-cloze-blank.active.filled-exam {
    box-shadow: 0 0 0 2px currentColor !important;
