    text-indent: 0 !important;
}
.proofread-analysis-header {
    margin-bottom: 14px;
    text-indent: 0 !important;
}
.proofread-analysis-title {
    font-size: 14px;
    font-weight: 800;
    color: #1e293b;
    letter-spacing: -0.01em;
}
.proofread-analysis-hint {
    font-size: 11px;
    font-weight: 600;
    color: #64748b;
    background: #f1f5f9;
    padding: 2px 8px;
