    font-weight: 700;
    padding: 2px 8px;
    border-radius: 6px;
}
.stream-type-tag.mod { background: #dcfce7; color: #166534; }
.stream-type-tag.del { background: #fee2e2; color: #991b1b; }
.stream-type-tag.add { background: #dbeafe; color: #1e40af; }
.stream-type-tag.cor { background: #ecfdf5; color: #047857; border: 1px solid #a7f3d0; }
.stream-card-body {
