}

/* Grammar Fill-in Input Field */
.grammar-fill-input {
    box-sizing: border-box;
    font-family: inherit;
    transition: all 0.2s ease;
}
.grammar-fill-input:focus {
    border-color: #007aff !important;
    box-shadow: 0 0 0 3px rgba(0, 122, 255, 0.15);
}

/* =============================================================
   优化二：语法填空 & 七选五“原文空格即时回填（Live Reflection）”
   ============================================================= */
.fill-blank-reflected {
    display: inline-block;
    vertical-align: baseline;
    text-indent: 0 !important;
    text-align: center;
    padding: 2px 8px;
    margin: 0 3px;
    font-size: 14px;
    font-weight: 700;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.25s var(--ios-spring);
    box-sizing: border-box;
    line-height: 1.4;
}
/* 1. 未填入空格 (默认未激活 - iOS System Grey) */
.fill-blank-reflected.unfilled {
    background: #f2f2f7 !important;
    color: #8e8e93 !important;
    border: 1px dashed #c7c7cc !important;
    box-shadow: none !important;
}

/* 2. 当前激活的空格 (方案二：苹果薄荷青/冰川蓝 iOS Cyan / Mint #00C7BE) */
.fill-blank-reflected.active,
.fill-blank-reflected.unfilled.active,
.fill-blank-reflected.filled-exam.active,
.fill-blank-reflected.exam.active {
    background: #e6fbf8 !important;
    color: #00827c !important;
    border: 1.5px solid #00c7be !important;
    box-shadow: 0 0 0 3px rgba(0, 199, 190, 0.22), 0 2px 6px rgba(0, 199, 190, 0.12) !important;
    animation: none !important;
}

/* 3. 已填入空格 (全真模考态: 与其他题型一致采用浅蓝底+蓝字经典空心态) */
.fill-blank-reflected.filled-exam,
.fill-blank-reflected.exam {
    background: #f0f6ff !important;
    color: #007aff !important;
    border: 1.5px solid #007aff !important;
    box-shadow: none !important;
    animation: none !important;
}

/* 4. 随刷随解正误态 */
.fill-blank-reflected.correct {
    background: #ecfdf5 !important;
    color: #059669 !important;
    border: 1.5px solid #10b981 !important;
    box-shadow: none !important;
    animation: none !important;
}
.fill-blank-reflected.wrong {
    background: #fef2f2 !important;
    color: #dc2626 !important;
    border: 1.5px solid #ef4444 !important;
    box-shadow: none !important;
    animation: none !important;
}
.fill-blank-reflected.correct.active {
    background: #ecfdf5 !important;
    color: #059669 !important;
    border: 1.5px solid #10b981 !important;
    box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.25) !important;
    animation: none !important;
}
.fill-blank-reflected.wrong.active {
    background: #fef2f2 !important;
    color: #dc2626 !important;
    border: 1.5px solid #ef4444 !important;
    box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.25) !important;
    animation: none !important;
}

/* 七选五空格动态展开 */
.seven-blank-reflected {
    display: block;
    text-indent: 0 !important;
    margin: 10px 0;
    padding: 10px 14px;
    border-radius: 12px;
    font-size: 14.5px;
    line-height: 1.6;
    font-weight: 600;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    cursor: pointer;
}
.seven-blank-reflected.unfilled {
    background: rgba(0, 0, 0, 0.03);
    border: 1.5px dashed rgba(0, 0, 0, 0.18);
    color: #64748b;
}
.seven-blank-reflected.unfilled.active {
    background: rgba(245, 158, 11, 0.08);
    border: 1.5px solid #f59e0b;
    color: #b45309;
    box-shadow: 0 2px 10px rgba(245, 158, 11, 0.12);
}
.seven-blank-reflected.filled {
    background: #f8fafc;
    border: 1.5px solid #0284c7;
    color: #0f172a;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}
.seven-blank-reflected.filled.correct {
    background: var(--correct-bg, #f0fdf4) !important;
    border: 1.5px solid var(--correct-green, #16a34a) !important;
    color: #0f172a !important;
}
.seven-blank-reflected.filled.wrong {
    background: var(--wrong-bg, #fef2f2) !important;
    border: 1.5px solid var(--wrong-red, #dc2626) !important;
    color: #0f172a !important;
}
.seven-blank-reflected.filled.exam {
    background: #f8fafc !important;
    border: 1.5px solid #0284c7 !important;
    color: #0f172a !important;
}
.seven-blank-reflected.filled.active {
    outline: 2px solid currentColor;
    outline-offset: 1px;
}

/* =============================================================
   高考短文改错 · 沉浸式自主做题与浮动交互系统
   ============================================================= */
.proofread-para {
    margin-bottom: 14px;
    text-indent: 2em;
    font-size: 16.5px;
    line-height: 2.3;
    color: #1e293b;
    font-weight: 500;
