    border-radius: 4px;
    padding: 1px 3px;
    transition: all 0.15s ease;
    display: inline-block;
}
.proof-word:hover {
    background: rgba(2, 132, 199, 0.12);
    color: #0284c7;
}
.proof-word.proof-word-selected {
    background: rgba(2, 132, 199, 0.18);
    box-shadow: 0 0 0 2px #0284c7;
    border-radius: 4px;
}

/* 学生自主修改批注手迹 */
.proof-user-item {
    cursor: pointer;
    display: inline-ruby;
    ruby-position: under;
    -webkit-ruby-position: after;
    margin: 0 3px;
    padding: 0 2px;
