}
/* 默认兜底及全真模考湖蓝手迹 (Student Lake Blue Exam Handwriting) */
.proof-user-item.proof-exam-blue.proof-mod-word .proof-orig-del,
.proof-user-item:not(.proof-correct):not(.proof-wrong).proof-mod-word .proof-orig-del {
    text-decoration: line-through;
    text-decoration-color: #0284c7;
    text-decoration-thickness: 1.2px;
    color: #0284c7;
    font-weight: 600;
}
.proof-user-item.proof-exam-blue.proof-mod-word .proof-sub-input,
.proof-user-item:not(.proof-correct):not(.proof-wrong).proof-mod-word .proof-sub-input {
    color: #0284c7;
    font-weight: 600;
    font-size: 0.88em;
    line-height: 1.1;
}
.proof-user-item.proof-exam-blue.proof-del-word del,
.proof-user-item:not(.proof-correct):not(.proof-wrong).proof-del-word del {
    text-decoration: line-through;
    text-decoration-color: #0284c7;
    text-decoration-thickness: 1.2px;
    color: #0284c7;
    font-weight: 600;
    padding: 0 1px;
}
.proof-user-item.proof-exam-blue.proof-add-word .proof-caret,
.proof-user-item:not(.proof-correct):not(.proof-wrong).proof-add-word .proof-caret {
    color: #0284c7;
    font-weight: 700;
    font-size: 1.1em;
    margin: 0 1px;
}
.proof-user-item.proof-exam-blue.proof-add-word .proof-sub-input,
.proof-user-item:not(.proof-correct):not(.proof-wrong).proof-add-word .proof-sub-input {
    color: #0284c7;
    font-weight: 600;
    font-size: 0.88em;
    line-height: 1.1;
}

/* 随刷随解模式：正确命中考点 (Green / Correct) */
.proof-user-item.proof-correct.proof-mod-word .proof-orig-del {
    text-decoration: line-through;
    text-decoration-color: #10b981;
    text-decoration-thickness: 1.2px;
    color: #10b981;
    font-weight: 600;
}
.proof-user-item.proof-correct.proof-mod-word .proof-sub-input {
    color: #059669;
    font-weight: 600;
    font-size: 0.88em;
    line-height: 1.1;
}
.proof-user-item.proof-correct.proof-del-word del {
    text-decoration: line-through;
    text-decoration-color: #10b981;
    text-decoration-thickness: 1.2px;
    color: #10b981;
    font-weight: 600;
    padding: 0 1px;
}
.proof-user-item.proof-correct.proof-add-word .proof-caret {
    color: #10b981;
    font-weight: 700;
    font-size: 1.1em;
    margin: 0 1px;
}
.proof-user-item.proof-correct.proof-add-word .proof-sub-input {
    color: #059669;
    font-weight: 600;
    font-size: 0.88em;
    line-height: 1.1;
}

/* 随刷随解模式：错误误改/直接红线划掉标识 (Red / Strikethrough Wrong) */
.proof-user-item.proof-wrong.proof-mod-word .proof-orig-del {
    text-decoration: line-through;
    text-decoration-color: #ef4444;
    text-decoration-thickness: 1.2px;
    color: #ef4444;
    font-weight: 600;
}
.proof-user-item.proof-wrong.proof-mod-word .proof-sub-input {
    color: #dc2626;
    font-weight: 600;
    font-size: 0.88em;
    line-height: 1.1;
}
.proof-user-item.proof-wrong.proof-del-word del {
    text-decoration: line-through;
    text-decoration-color: #ef4444;
    text-decoration-thickness: 1.2px;
    color: #ef4444;
    font-weight: 600;
    padding: 0 1px;
}
.proof-user-item.proof-wrong.proof-add-word .proof-caret {
    color: #ef4444;
    font-weight: 700;
    font-size: 1.1em;
    margin: 0 1px;
}
.proof-user-item.proof-wrong.proof-add-word .proof-sub-input {
    color: #dc2626;
    font-weight: 600;
    font-size: 0.88em;
    line-height: 1.1;
}

/* 即时正误状态符号（紧跟在下方标注内，不影响主干文本排版） */
.proof-sub-mark {
    font-size: 11px;
    font-weight: 900;
