/* 浮动操作气泡 (Floating Action Popover) */
.word-action-popover {
    position: absolute;
    z-index: 1100;
    background: rgba(30, 41, 59, 0.96);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    padding: 8px 12px;
    border-radius: 20px;
    box-shadow: 0 12px 28px rgba(0, 0, 0, 0.28);
    transform: translate(-50%, -100%) translateY(-10px);
    animation: popoverFadeIn 0.2s cubic-bezier(0.16, 1, 0.3, 1);
    white-space: nowrap;
    min-width: 180px;
    max-width: 90vw;
}
.word-action-popover::after {
    content: '';
    position: absolute;
    bottom: -6px;
    left: 50%;
    transform: translateX(-50%);
    border-width: 6px 6px 0;
    border-style: solid;
    border-color: rgba(30, 41, 59, 0.96) transparent transparent;
}
.word-action-popover.popover-flip-below {
    transform: translate(-50%, 0) translateY(8px);
    animation: popoverFadeInBelow 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}
.word-action-popover.popover-flip-below::after {
    bottom: auto;
    top: -6px;
    border-width: 0 6px 6px;
    border-color: transparent transparent rgba(30, 41, 59, 0.96);
}
@keyframes popoverFadeIn {
    from { opacity: 0; transform: translate(-50%, -100%) translateY(-2px) scale(0.95); }
    to { opacity: 1; transform: translate(-50%, -100%) translateY(-10px) scale(1); }
}
@keyframes popoverFadeInBelow {
    from { opacity: 0; transform: translate(-50%, 0) translateY(2px) scale(0.95); }
    to { opacity: 1; transform: translate(-50%, 0) translateY(8px) scale(1); }
}

.popover-word-title {
    font-size: 12px;
    color: #cbd5e1;
    margin-bottom: 6px;
    text-align: center;
}
