/* === css/written_subjective.css === */
/* =============================================================
   优化四：雅思 / 托福专属题型组件样式
   ============================================================= */
/* 雅思 TFNG (True / False / Not Given) */
.tfng-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    width: 100%;
    margin-top: 10px;
}
.tfng-btn {
    height: 48px;
    border-radius: 14px;
    border: 1.5px solid #e2e8f0;
    background: #ffffff;
    font-size: 15px;
    font-weight: 700;
    color: #334155;
    cursor: pointer;
    transition: all 0.2s var(--ios-spring);
    display: flex;
    align-items: center;
    justify-content: center;
}
.tfng-btn:hover {
    border-color: #007aff;
    background: rgba(0, 122, 255, 0.04);
    transform: translateY(-1px);
}
.tfng-btn.selected {
    border-color: #007aff;
    background: #007aff;
    color: #ffffff;
    box-shadow: 0 4px 12px rgba(0, 122, 255, 0.25);
}
.tfng-btn.correct {
    border-color: #10b981 !important;
    background: #10b981 !important;
    color: #ffffff !important;
}
.tfng-btn.wrong {
    border-color: #ef4444 !important;
    background: #ef4444 !important;
    color: #ffffff !important;
}

/* 托福黑方块插句 (Sentence Insertion) */
.sentence-insert-square {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    background: #1e293b;
    color: #ffffff;
    border-radius: 4px;
    font-size: 12px;
    font-weight: 800;
    cursor: pointer;
    margin: 0 4px;
    vertical-align: middle;
    transition: all 0.2s ease;
}
.sentence-insert-square:hover {
    background: #007aff;
    transform: scale(1.15);
}
.sentence-insert-square.active {
    background: #007aff;
    box-shadow: 0 0 0 3px rgba(0, 122, 255, 0.35);
}
.sentence-inserted-content {
    background: #f0fdf4;
    border: 1.5px solid #22c55e;
    color: #15803d;
    padding: 3px 8px;
    border-radius: 6px;
    font-weight: 600;
    margin: 0 4px;
    animation: insertFadeIn 0.3s ease;
}
.sentence-inserted-content.wrong {
    background: #fef2f2 !important;
    border-color: #ef4444 !important;
    color: #b91c1c !important;
}
.sentence-inserted-content.exam {
    background: #e0f2fe !important;
    border-color: #0284c7 !important;
    color: #0284c7 !important;
}
@keyframes insertFadeIn {
    from { opacity: 0; transform: scale(0.95); }
    to { opacity: 1; transform: scale(1); }
}

/* 改错主动做题任务条 (1~10 任务微标签栏) */
.proofread-task-strip {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 14px;
    overflow-x: auto;
    padding-bottom: 4px;
    scrollbar-width: thin;
}
.proofread-strip-chip {
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 13px;
    font-weight: 700;
    border: 1.5px solid #e2e8f0;
    background: #ffffff;
    color: #475569;
    cursor: pointer;
    white-space: nowrap;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 4px;
}
.proofread-strip-chip:hover {
    border-color: #0284c7;
    color: #0284c7;
    transform: translateY(-1px);
}
.proofread-strip-chip.active {
    border-color: #f59e0b;
    background: #fffbeb;
    color: #d97706;
    box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.2);
}
.proofread-strip-chip.done {
    border-color: #10b981;
    background: #ecfdf5;
    color: #059669;
}

/* 改错缺词插入插槽 (Caret Add Slot) */
.proofread-add-slot {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 16px;
    height: 22px;
    margin: 0 3px;
    padding: 0 4px;
    cursor: pointer;
    color: #0284c7;
    background: rgba(2, 132, 199, 0.08);
    border: 1px dashed #38bdf8;
    border-radius: 6px;
    font-size: 13px;
    font-weight: 800;
    line-height: 1;
    vertical-align: middle;
    transition: all 0.2s ease;
