    top: 0;
    bottom: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: rgba(100, 116, 139, 0.45);
    font-weight: 500;
    font-size: inherit;
    line-height: inherit;
    pointer-events: none;
    user-select: none;
    z-index: 2;
    transition: opacity 0.12s ease;
}

.hint-ghost-start {
    left: 4px;
}

.hint-ghost-end {
    right: 4px;
}

@media (max-width: 600px) {
    .hint-ghost-start {
        left: 3px;
    }
    .hint-ghost-end {
        right: 3px;
    }
}

.cloze-input-wrap.has-value .hint-ghost-start,
.cloze-input-wrap.has-value .hint-ghost-end {
    opacity: 0 !important;
    pointer-events: none !important;
}

.cloze-input.correct-fused {
    border: none !important;
    background: transparent !important;
    color: #111113 !important;
    font-weight: 500 !important;
    cursor: default;
    box-shadow: none !important;
    transform: none !important;
}

.cloze-word-done {
