}

/* 🌟 Fluid Horizontal Swipe Slide Transition */
.dict-hero-sentence.swipe-slide-left {
    animation: dictSwipeLeft 0.18s cubic-bezier(0.32, 0.72, 0, 1) backwards;
}
.dict-hero-sentence.swipe-slide-right {
    animation: dictSwipeRight 0.18s cubic-bezier(0.32, 0.72, 0, 1) backwards;
}

@keyframes dictSwipeLeft {
    0% { opacity: 0.72; transform: translate3d(18px, 0, 0); }
    100% { opacity: 1; transform: translate3d(0, 0, 0); }
}

@keyframes dictSwipeRight {
    0% { opacity: 0.72; transform: translate3d(-18px, 0, 0); }
    100% { opacity: 1; transform: translate3d(0, 0, 0); }
}

/* 🌟 Auto-Advance Next Sentence Pulse */
.btn-nav-action.auto-advancing,
.dict-key-next.auto-advancing {
