    animation: pulseNextAuto 1.2s ease-in-out infinite alternate !important;
}

@keyframes pulseNextAuto {
    0% { transform: scale(1); box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.2); }
    100% { transform: scale(1.03); box-shadow: 0 0 0 5px rgba(37, 99, 235, 0.35); }
}

.island-left-group {
