}

/* Standalone White Tactile Pill Buttons (Matching Return Button UX) */
.btn-island-pill {
    height: 38px;
    padding: 0 15px;
    border-radius: 999px;
    background: #ffffff;
    border: 1px solid rgba(0, 0, 0, 0.05);
