}

/* Standalone Black Center Play Pill */
.btn-island-play {
    height: 38px;
    padding: 0 20px 0 16px;
    border-radius: 999px;
    background: #111113;
    color: #ffffff;
    border: none;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.18);
    transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
    user-select: none;
}

.btn-island-play:hover {
    background: #000000;
    transform: translateY(-1.5px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
}

.btn-island-play:active {
    transform: scale(0.95);
}

.island-wave-bars {
    display: flex;
    align-items: center;
    gap: 2px;
    height: 12px;
    margin-left: 2px;
}

.island-wave-bars span {
    width: 2px;
    height: 3px;
    background: rgba(255, 255, 255, 0.4);
    border-radius: 1px;
    transition: height 0.15s ease;
}

.island-wave-bars.playing span {
    background: #ffffff;
    animation: islandWave 0.45s ease-in-out infinite alternate;
}

.island-wave-bars.playing span:nth-child(1) { animation-delay: 0.05s; }
.island-wave-bars.playing span:nth-child(2) { animation-delay: 0.15s; }
.island-wave-bars.playing span:nth-child(3) { animation-delay: 0.25s; }

@keyframes islandWave {
    0% { height: 3px; }
    100% { height: 12px; }
}

/* ⏳ Island Play Button Buffering / Network Loading State */
.btn-island-play.buffering {
    background: #1c1c1e !important;
    opacity: 0.94;
    cursor: wait;
}

.btn-island-play.buffering #zen-play-icon {
    display: inline-block;
    animation: zenSpinPulse 1.4s ease-in-out infinite;
}

@keyframes zenSpinPulse {
    0% { transform: scale(1) rotate(0deg); opacity: 0.7; }
    50% { transform: scale(1.15) rotate(180deg); opacity: 1; }
    100% { transform: scale(1) rotate(360deg); opacity: 0.7; }
}

.island-wave-bars.buffering span {
    animation: islandWaveBuffering 0.9s ease-in-out infinite alternate;
    background: rgba(255, 255, 255, 0.45);
}

.island-wave-bars.buffering span:nth-child(1) { animation-delay: 0s; }
.island-wave-bars.buffering span:nth-child(2) { animation-delay: 0.18s; }
.island-wave-bars.buffering span:nth-child(3) { animation-delay: 0.36s; }

@keyframes islandWaveBuffering {
    0% { height: 3px; opacity: 0.3; }
    100% { height: 7px; opacity: 0.85; }
}


.btn-island-circle-nav {
    width: 34px;
