/* 🎙️ Dictation Audio Settings Modal / Action Sheet */
.dict-settings-mask {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 9999;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    animation: fadeInModal 0.22s ease-out;
}

.dict-settings-sheet {
    width: 100%;
    max-width: 480px;
    max-height: calc(100vh - max(var(--toy-safe-top, 0px), env(safe-area-inset-top, 0px), 24px));
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
    background: #FFFFFF;
    border-radius: 28px 28px 0 0;
    padding: 24px 20px calc(28px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px))) 20px;
    box-sizing: border-box;
    box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.12);
    display: flex;
    flex-direction: column;
    gap: 20px;
    animation: slideUpSheet 0.28s cubic-bezier(0.16, 1, 0.3, 1);
}

.dict-settings-sheet > * {
    flex-shrink: 0;
}

@keyframes slideUpSheet {
    from { transform: translateY(100%); }
    to { transform: translateY(0); }
}

@keyframes fadeInModal {
    from { opacity: 0; }
    to { opacity: 1; }
}

.dict-settings-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-bottom: 4px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.05);
}

.dict-settings-title {
    font-size: 16.5px;
    font-weight: 850;
    color: #0F172A;
}

.dict-settings-close-btn {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: #F1F5F9;
    border: none;
    color: #64748B;
    font-size: 14px;
    font-weight: 700;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
}

.dict-settings-section {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.dict-settings-section-title {
    font-size: 12.5px;
    font-weight: 800;
    color: #64748B;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.dict-settings-options {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}

.dict-settings-options.col {
    grid-template-columns: 1fr;
}

.dict-opt-pill {
    padding: 12px 14px;
    border-radius: 16px;
    border: 1.5px solid #E2E8F0;
    background: #F8FAFC;
    color: #334155;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    font-size: 14px;
    font-weight: 750;
    transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
}

.dict-opt-pill.row-pill {
    justify-content: space-between;
    text-align: left;
    padding: 12px 16px;
}

.dict-opt-pill .opt-left {
    display: flex;
    align-items: center;
    gap: 12px;
}

.dict-opt-pill .opt-icon {
    font-size: 20px;
}

.dict-opt-pill .opt-texts {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.dict-opt-pill .opt-main {
    font-size: 14px;
    font-weight: 800;
    color: #0F172A;
}

.dict-opt-pill .opt-sub {
    font-size: 11.5px;
    font-weight: 600;
