    font-weight: 550;
    color: #111113;
    cursor: pointer;
    user-select: none;
    -webkit-user-select: none;
    touch-action: manipulation;
    transition: transform 0.08s ease, background-color 0.08s ease;
    box-sizing: border-box;
    padding: 0;
}

@media (max-width: 360px) {
    .dict-key {
        height: 38px;
        font-size: 17px;
    }
}

.dict-key-letter {
    flex: 1;
    min-width: 0;
}

.dict-key:active,
.dict-key.is-pressed {
    background-color: #cbd5e1 !important;
    transform: scale(0.93);
    box-shadow: 0 0 1px rgba(0, 0, 0, 0.1);
}

/* Function Keys: Replay & Backspace */
.dict-key-fn {
    background: #d1d5db;
    color: #1f2937;
    font-size: 12.5px;
    font-weight: 650;
    flex: 1.35;
    gap: 3px;
    box-shadow: 0 1px 0 rgba(0, 0, 0, 0.15), 0 2px 2px rgba(0, 0, 0, 0.04);
}

.dict-key-replay {
    flex: 1.35;
    background: #e2e8f0;
    color: #1e293b;
    font-size: 13px;
    font-weight: 650;
    gap: 3px;
}

.dict-key-replay .dict-key-icon {
    font-size: 14px;
    font-weight: 800;
}

.dict-key-backspace {
    flex: 1.35;
}

.dict-key-backspace svg {
    width: 21px;
    height: 21px;
    stroke: #1f2937;
}

/* Action Keys (Row 4: ← 上一空 | ← 上句 | 下句 ➔ | 下一空 →) */
.dict-key-action {
    height: 42px;
    border-radius: 10px;
    font-size: 13px;
    font-weight: 700;
    gap: 4px;
    padding: 0 4px;
}

/* 上一空 / 下一空: 处于左右两侧最顺手位置，放大宽度，彻底避免误触 */
.dict-key-prev-blank,
.dict-key-next-blank {
    flex: 1.38;
    background: #ffffff;
    color: #0f172a;
    border: 1px solid rgba(0, 0, 0, 0.1);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.2px;
}

.dict-key-prev-blank:active,
.dict-key-next-blank:active {
    background: #f1f5f9 !important;
}

/* 上一句: 居中偏左，紧凑小巧 */
.dict-key-prev {
    flex: 0.95;
    background: #f8fafc;
    color: #64748b;
    border: 1px solid rgba(0, 0, 0, 0.06);
    font-size: 12.5px;
    font-weight: 600;
}

.dict-key-prev[disabled] {
    opacity: 0.35;
    pointer-events: none;
}

/* 下一句: 居中偏右，比例适度缩小，避免喧宾夺主 */
.dict-key-next {
    flex: 1.05;
    background: #007aff;
    color: #ffffff;
    box-shadow: 0 2px 8px rgba(0, 122, 255, 0.28);
    font-size: 12.5px;
    font-weight: 700;
}

.dict-key-next:active {
    background: #0062cc !important;
}

.dict-key-next.pulse-success {
    background: #34c759 !important;
    box-shadow: 0 2px 12px rgba(52, 199, 89, 0.45);
    animation: keyNextPulse 1.2s infinite alternate ease-in-out;
}

/* Keyboard Switcher Toolbar Button (Virtual KB -> System KB) */
.dict-kb-tool-btn.dict-kb-switch-native-btn {
    color: #007aff !important;
    font-weight: 650 !important;
}

/* Canvas Header Keyboard Toggle Pill (Permanently hidden in card header - moved to top-right settings popover menu) */
.dict-kb-toggle-pill,
#btn-dict-canvas-kb-toggle {
    display: none !important;
}

@keyframes keyNextPulse {
    0% { transform: scale(1); box-shadow: 0 2px 8px rgba(52, 199, 89, 0.35); }
    100% { transform: scale(1.03); box-shadow: 0 4px 16px rgba(52, 199, 89, 0.6); }
}

.cloze-input-wrap:not(.has-value):not(.has-focus) {
    box-shadow: none !important;
}

/* Bottom Nav Keyboard Toggle Button (Permanently hidden as moved to 3-dots top settings) */
#btn-dict-nav-keyboard {
    display: none !important;
}
#dictation-nav-group .btn-nav-action {
    padding: 0 16px;
}
@media (max-width: 380px) {
    #dictation-nav-group .btn-nav-action {
        padding: 0 12px;
        font-size: 12px;
    }
}



