    border-radius: 999px;
    background: rgba(255, 255, 255, 0.94);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: none;
    color: #18181b;
    font-size: 9.5px;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.02em;
    line-height: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
    box-shadow:
        0 0 0 0.5px rgba(15, 23, 42, 0.14),
        0 2px 6px rgba(0, 0, 0, 0.22);
    box-sizing: border-box;
}
.dict-loading-spinner {
    display: inline-block;
    width: 14px;
    height: 14px;
    border: 2px solid rgba(0, 122, 255, 0.25);
    border-top-color: #007aff;
    border-radius: 50%;
    animation: dict-spin 0.6s linear infinite;
}
@keyframes dict-spin {
    to { transform: rotate(360deg); }
}
.popover-word {
    font-size: 17px;
    font-weight: 800;
    color: var(--ink-primary);
}
.popover-phonetic {
    font-size: 12px;
    font-weight: 600;
    color: var(--accent-gold);
}
.popover-def {
    font-size: 13.5px;
    line-height: 1.45;
    color: #2c2c2e;
    font-weight: 500;
}
.popover-def-line {
    margin-bottom: 5px;
    line-height: 1.5;
    font-size: 13.5px;
    color: var(--ink-primary);
    word-break: break-word;
}
.popover-def-line:last-child {
    margin-bottom: 0;
}
.popover-pos-tag {
    color: var(--accent-gold);
    font-weight: 700;
    margin-right: 4px;
}

/* Lookup Mode Active State (查词模式开启态) */
body.lookup-mode-active .dict-word {
    cursor: default;
    border-radius: 4px;
    transition: background 0.12s ease, color 0.12s ease;
}
body.lookup-mode-active .dict-word.valid-entry,
body.lookup-mode-active .dict-word.dict-active-highlight {
    cursor: pointer !important;
    background: rgba(0, 122, 255, 0.14) !important;
    color: #0066cc !important;
    text-decoration: none !important;
}
/* Strict Lookup Mode Interception - Eliminate all option hover/active/touch highlights */
body.lookup-mode-active .opt-btn,
body.lookup-mode-active .opt-btn:hover,
body.lookup-mode-active .opt-btn:active,
body.lookup-mode-active .opt-btn:focus,
body.lookup-mode-active .word-bank-opt-btn,
body.lookup-mode-active .word-bank-opt-btn:hover,
body.lookup-mode-active .word-bank-opt-btn:active,
body.lookup-mode-active .word-bank-opt-btn:focus,
body.lookup-mode-active .matching-paragraph-opt-btn,
body.lookup-mode-active .matching-paragraph-opt-btn:hover,
body.lookup-mode-active .matching-paragraph-opt-btn:active,
body.lookup-mode-active .matching-paragraph-opt-btn:focus {
    cursor: default !important;
    transform: none !important;
    box-shadow: none !important;
    -webkit-tap-highlight-color: transparent !important;
}

body.lookup-mode-active .opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state),
body.lookup-mode-active .opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state):hover,
body.lookup-mode-active .opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state):active,
body.lookup-mode-active .opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state):focus {
    border: var(--opt-border) !important;
    background-color: #ffffff !important;
    box-shadow: none !important;
    transform: none !important;
}

body.lookup-mode-active .word-bank-opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state),
body.lookup-mode-active .word-bank-opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state):hover,
body.lookup-mode-active .word-bank-opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state):active {
    border-color: rgba(60, 60, 67, 0.12) !important;
    background-color: #ffffff !important;
    box-shadow: none !important;
    transform: none !important;
}

body.lookup-mode-active .matching-paragraph-opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state),
body.lookup-mode-active .matching-paragraph-opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state):hover,
body.lookup-mode-active .matching-paragraph-opt-btn:not(.correct-state):not(.wrong-state):not(.exam-selected-state):active {
    border-color: rgba(60, 60, 67, 0.12) !important;
    background-color: #ffffff !important;
    box-shadow: none !important;
    transform: none !important;
}

/* Floating Lookup Mode Indicator Banner (Subtle Minimal White Card Style) */
.lookup-mode-floating-bar {
    display: none;
    align-items: center;
    justify-content: space-between;
    background: #ffffff;
    color: var(--ink-primary);
    padding: 8px 14px;
    border-radius: 12px;
    margin-bottom: 14px;
    font-size: 13px;
    font-weight: 600;
    border: 1px solid rgba(0, 0, 0, 0.08);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03);
    animation: fadeInSlideDown 0.2s var(--ios-spring);
    z-index: 20;
}

.lookup-bar-text {
    display: flex;
    align-items: center;
    gap: 6px;
    color: #48484a;
    font-size: 13px;
}

.lookup-bar-exit-btn {
    background: rgba(0, 0, 0, 0.04);
    border: 1px solid rgba(0, 0, 0, 0.07);
    color: #636366;
    padding: 4px 10px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
    flex-shrink: 0;
}

.lookup-bar-exit-btn:hover {
    background: rgba(0, 0, 0, 0.08);
    color: var(--ink-primary);
}

.lookup-bar-exit-btn:active {
    transform: scale(0.96);
}

/* iOS Sheet Drawer & Modals */
.drawer-mask, .modal-mask {
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 10000 !important;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity 0.22s cubic-bezier(0.25, 1, 0.5, 1), visibility 0s linear 0.22s;
    transform: translateZ(0);
    -webkit-transform: translateZ(0);
}
.drawer-mask.active, .modal-mask.active {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transition: opacity 0.22s cubic-bezier(0.25, 1, 0.5, 1), visibility 0s linear 0s;
}

.drawer-box {
    background-color: #ffffff !important;
    background: #ffffff !important;
    border: var(--card-border);
    box-shadow: inset 0 0.5px 0 rgba(255, 255, 255, 0.96), 0 -12px 42px rgba(15, 23, 42, 0.16);
    border-top-left-radius: 26px;
    border-top-right-radius: 26px;
    padding: clamp(18px, 3.5vw, 24px) clamp(16px, 4vw, 28px) calc(24px + max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px))) clamp(16px, 4vw, 28px);
    max-height: calc(100vh - max(var(--toy-safe-top, 0px), env(safe-area-inset-top, 0px), 16px));
    width: min(100%, 680px);
    box-sizing: border-box;
    align-self: flex-end;
    transform: translateY(100%) translateZ(0);
    -webkit-transform: translateY(100%) translateZ(0);
    transition: transform 0.3s cubic-bezier(0.32, 0.72, 0, 1);
    will-change: transform;
    -webkit-backface-visibility: hidden;
    backface-visibility: hidden;
    overflow: hidden;
}
.drawer-mask.active .drawer-box {
    transform: translateY(0) translateZ(0);
    -webkit-transform: translateY(0) translateZ(0);
}
.drawer-box::before {
    content: "";
    display: block;
    width: 38px;
    height: 4.5px;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.16);
    margin: -6px auto 12px auto;
}

@media (min-width: 640px) {
    .drawer-box {
        width: 740px !important;
        max-width: 92% !important;
        margin: 0 auto 24px auto !important;
        border-radius: 28px !important;
    }
}
.drawer-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
    font-size: 17px;
    font-weight: 700;
}
.drawer-section-nav-wrapper {
    position: relative;
    width: 100%;
    margin-bottom: 14px;
}

.drawer-section-nav-wrapper::before,
.drawer-section-nav-wrapper::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 1px;
    width: 28px;
    pointer-events: none;
    transition: opacity 0.2s ease;
    opacity: 0;
    z-index: 3;
}

.drawer-section-nav-wrapper::before {
    left: 0;
    background: linear-gradient(to right, #ffffff, rgba(255, 255, 255, 0));
}

.drawer-section-nav-wrapper::after {
    right: 0;
    background: linear-gradient(to left, #ffffff, rgba(255, 255, 255, 0));
}

.drawer-section-nav-wrapper.can-scroll-left::before {
    opacity: 1;
}

.drawer-section-nav-wrapper.can-scroll-right::after {
    opacity: 1;
}

.drawer-section-nav {
    display: flex;
    align-items: center;
    gap: 8px;
    overflow-x: auto;
    padding: 2px 4px 12px 4px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.06);
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
    cursor: grab;
    user-select: none;
    -webkit-user-select: none;
}
.drawer-section-nav:active {
    cursor: grabbing;
}
.drawer-section-nav::-webkit-scrollbar {
    display: none;
}
.drawer-sec-pill {
    flex-shrink: 0;
    padding: 6px 13px;
    border-radius: 999px;
    font-size: 12.5px;
    font-weight: 600;
    background: #f2f2f5;
    color: var(--ink-sub);
    border: 1px solid rgba(15, 23, 42, 0.055);
    cursor: pointer;
    transition: transform 0.14s var(--ios-press), background-color 0.18s ease, color 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
    white-space: nowrap;
    display: flex;
    align-items: center;
    gap: 4px;
    user-select: none;
    -webkit-user-select: none;
}
@media (hover: hover) and (pointer: fine) {
    .drawer-sec-pill:hover:not(.active) {
        background: #e8e8ec;
        color: var(--ink-primary);
    }
}
.drawer-sec-pill:active {
    transform: scale(0.96);
}
.drawer-sec-pill.active {
    background: #1c1c1e;
    color: #ffffff;
    border-color: #1c1c1e;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}
.drawer-q-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(52px, 1fr));
    gap: 10px;
    max-height: calc(100vh - 220px - max(var(--toy-safe-top, 0px), env(safe-area-inset-top, 0px)) - max(var(--toy-safe-bottom, 0px), env(safe-area-inset-bottom, 0px)));
    overflow-y: auto;
    padding: 4px 2px;
}
.q-chip {
    height: 42px;
    border-radius: 12px;
    border: var(--opt-border);
    box-shadow: var(--opt-resting-shadow);
    background: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.12s var(--ios-press), background-color 0.16s ease, border-color 0.16s ease, color 0.16s ease;
}
.q-chip:active {
    transform: scale(0.94);
}
.q-chip.correct { background: var(--correct-bg); border-color: var(--correct-green); color: var(--correct-green); }
.q-chip.wrong { background: var(--wrong-bg); border-color: var(--wrong-red); color: var(--wrong-red); }
.q-chip.is-locked-chip {
    background: #f8f8fa !important;
    color: #8e8e93 !important;
    border-color: rgba(0, 0, 0, 0.08) !important;
    position: relative;
}
.q-chip.is-locked-chip::after {
    content: '🔒';
    position: absolute;
    top: 2px;
    right: 3px;
    font-size: 9px;
    line-height: 1;
    opacity: 0.75;
}

.modal-card {
    background: var(--paper-card);
    border: var(--card-border);
    box-shadow: 0 20px 60px rgba(0,0,0,0.2);
    border-radius: 24px;
    padding: clamp(22px, 4vw, 34px) clamp(20px, 4.5vw, 36px);
    width: min(92vw, 440px);
    max-height: 88vh;
    overflow-y: auto;
    box-sizing: border-box;
    text-align: center;
    transform: scale(0.9) translateY(20px);
    transition: transform 0.35s var(--ios-sheet);
}
.modal-mask.active .modal-card {
    transform: scale(1) translateY(0);
}
.score-num {
    font-size: 64px;
    font-weight: 800;
    color: var(--accent-gold);
    margin: 12px 0;
}
.btn-modal-primary {
    background: var(--accent-gold);
    color: #fff;
    font-size: 16px;
    font-weight: 600;
    padding: 13px 32px;
    border-radius: 999px;
    border: none;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12);
    cursor: pointer;
    transition: all 0.2s var(--ios-spring);
    width: 100%;
    margin-top: 18px;
}

/* Custom Toy Toast Bar */
.toy-toast-bar {
    position: fixed;
    top: 24px;
    left: 50%;
    transform: translateX(-50%) translateY(-30px);
    background: #1c1c1e;
    color: #ffffff;
    font-size: 13.5px;
    font-weight: 600;
    padding: 10px 22px;
    border-radius: 999px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.25);
    transition: all 0.3s var(--ios-spring);
    z-index: 2000;
    opacity: 0;
    pointer-events: none;
}
.toy-toast-bar.show {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
}

/* Keyboard Shortcut Badge */
.kbd-badge {
    display: none;
    font-size: 11px;
    font-weight: 700;
    font-family: monospace;
    background: #eef3f7;
    color: #5c6878;
    padding: 2px 6px;
    border-radius: 4px;
    border: 1px solid #d7e2ea;
    margin-left: 6px;
    vertical-align: middle;
}

